{"code": "import nanosurf, time, os, sys, traceback

try:
    spm = nanosurf.SPM()
    app = spm.application
    scan = app.Scan
    opmode = app.OperatingMode
    # set parameters
    scan.ImageWidth = 10e-6
    scan.ImageHeight = 10e-6
    scan.Points = 128
    scan.Lines = 128
    scan.Scantime = 0.4  # time per line in seconds
    # set tapping mode if available
    try:
        opmode.Mode = 'Tapping'
    except Exception:
        # fallback to AC mode attribute
        if hasattr(opmode, 'SetMode'):
            opmode.SetMode('Tapping')
    # start scan
    if hasattr(app, 'StartScan'):
        app.StartScan()
    elif hasattr(app, 'StartAcquisition'):
        app.StartAcquisition()
    else:
        raise RuntimeError('No start scan method found')
    # wait for completion: approximate total time
    total_time = 0.4 * 128 + 5  # add buffer
    time.sleep(total_time)
    # assume image saved in default folder, retrieve latest file
    # common path maybe in user's Documents or a specific folder
    possible_dirs = [
        os.path.expanduser('~/Desktop/AFM_Images'),
        os.path.expanduser('~/AFM_Images'),
        'C:/AFM_Images',
        'C:/Users/Admin/Desktop/AFM_Images'
    ]
    latest_file = None
    latest_mtime = 0
    for d in possible_dirs:
        if os.path.isdir(d):
            for f in os.listdir(d):
                fp = os.path.join(d, f)
                if os.path.isfile(fp):
                    mtime = os.path.getmtime(fp)
                    if mtime > latest_mtime:
                        latest_mtime = mtime
                        latest_file = fp
    if latest_file:
        print('IMAGE_PATH:', latest_file)
    else:
        print('IMAGE_PATH: NOT_FOUND')
except Exception as e:
    traceback.print_exc()
    sys.exit(1)
"}

